 {"id": "PEDS-C45-048", "sec": "AIS puberty and management", "page": 210, "q": "\"Apparent change of gender\" at puberty is described in —", "opts": ["Partial androgen insensitivity syndrome", "Complete AIS", "Turner syndrome", "Constitutional delay"], "ans": 0, "exp": "Spontaneous virilization with apparent change of gender occurs when resistance is partial (features vary with severity of resistance). (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-049", "sec": "AIS puberty and management", "page": 210, "q": "A child raised as a girl begins virilising at puberty (voice deepening, clitoral growth). The likely mechanism —", "opts": ["Exogenous androgens", "Partial androgen insensitivity with rising testosterone", "Congenital adrenal hyperplasia", "Ovarian tumour"], "ans": 1, "exp": "Puberty: increased testosterone → spontaneous virilization → apparent change of gender (partial resistance). (Book p210)", "type": "case", "stem": "A 12-year-old raised as a girl presents with deepening voice, clitoromegaly and increasing muscle mass. Karyotype is 46,XY and testosterone is very high."},
 {"id": "PEDS-C45-050", "sec": "AIS puberty and management", "page": 210, "q": "Clinical hallmark of AIS in childhood is female-like features with the child —", "opts": ["Reassigned at puberty", "Raised gender-neutral", "Raised as a girl", "Raised as a boy"], "ans": 2, "exp": "Female-like features: child raised as a girl. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-051", "sec": "AIS puberty and management", "page": 210, "q": "Management of AIS includes —", "opts": ["Gonadotropin suppression in infancy", "Testosterone injections in classical AIS girls", "No treatment required", "Replacement of sex steroids"], "ans": 3, "exp": "Management: replacement of sex steroids. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-052", "sec": "AIS puberty and management", "page": 210, "q": "In AIS raised female, the estrogen used for replacement is —", "opts": ["Ethinylestradiol", "Conjugated equine estrogen", "Estradiol valerate", "Transdermal estradiol"], "ans": 0, "exp": "In females: ethinylestradiol. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-053", "sec": "AIS puberty and management", "page": 210, "q": "Ethinylestradiol replacement in AIS (raised female) is started beyond ___ years of age.", "opts": ["16 years", "12 years", "10 years", "14 years"], "ans": 1, "exp": "In females: ethinylestradiol started after 12 years. (Book p210)", "type": "fill"},
 {"id": "PEDS-C45-054", "sec": "AIS puberty and management", "page": 210, "q": "Oral progesterone is added to AIS (female) hormone replacement —", "opts": ["5 years after estrogen", "Only after surgery", "2 years after estrogen", "Immediately with estrogen"], "ans": 2, "exp": "Oral progesterone 2 years later (to achieve break-through bleeding). (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-055", "sec": "AIS puberty and management", "page": 210, "q": "The purpose of adding oral progesterone in AIS (raised female) is to achieve —", "opts": ["Breast growth", "Bone mineralisation", "Height gain", "Break-through bleeding"], "ans": 3, "exp": "Oral progesterone (to achieve break-through bleeding). (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-056", "sec": "AIS puberty and management", "page": 210, "q": "In AIS raised male (partial forms), replacement therapy uses —", "opts": ["Testosterone", "Dihydrotestosterone gel", "hCG injections only", "Aromatase inhibitors"], "ans": 0, "exp": "In males: testosterone. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-057", "sec": "AIS puberty and management", "page": 210, "q": "Early (premature) administration of sex steroids in AIS causes —", "opts": ["Gigantomastia", "Early fusion of epiphysis → short stature", "Tall stature", "Improved final height"], "ans": 1, "exp": "Early administration → early fusion of epiphysis → short stature. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-058", "sec": "AIS puberty and management", "page": 210, "q": "Sex steroid replacement in AIS must be timed carefully because early administration fuses the ___.", "opts": ["Pelvic outlet", "Vertebral plates only", "Epiphysis", "Skull sutures"], "ans": 2, "exp": "Early administration → early fusion of epiphysis → short stature. (Book p210)", "type": "fill"},
 {"id": "PEDS-C45-059", "sec": "AIS puberty and management", "page": 210, "q": "Match the AIS management element with its detail:", "opts": ["A-1, B-3, C-4, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "ans": 3, "exp": "Correct pairs: Females→Ethinylestradiol; Males→Testosterone; Progesterone→2 years later, breakthrough bleeding; Early administration→Short stature from early epiphyseal fusion. (Book p210)", "type": "match", "pairs": [["Females (AIS)", "Testosterone"], ["Males (AIS)", "Ethinylestradiol"], ["Progesterone timing", "Short stature from early epiphyseal fusion"], ["Early administration", "2 years later, breakthrough bleeding"]]},
 {"id": "PEDS-C45-060", "sec": "AIS puberty and management", "page": 210, "q": "A girl with classical AIS asks why she cannot have periods. The best explanation —", "opts": ["She has no uterus (46,XY, AMH acted)", "Her ovaries are streak", "Her endometrium is infantile", "She has a transverse vaginal septum"], "ans": 0, "exp": "In AIS the 46,XY gonad is a testis producing AMH → uterus absent; estrogen (aromatized) develops breasts, but no menses is possible. (Book p210)", "type": "case", "stem": "A 16-year-old with classical AIS on estrogen replacement asks about future menstruation."},
 {"id": "PEDS-C45-061", "sec": "AIS puberty and management", "page": 210, "q": "Starting ethinylestradiol at 8 years of age in AIS would risk —", "opts": ["Adrenal insufficiency", "Short stature from early epiphyseal fusion", "Delayed puberty", "Ovarian cancer"], "ans": 1, "exp": "Early administration → early fusion of epiphysis → short stature; hence estrogen is started after 12 years. (Book p210)", "type": "mcq"},
 {"id": "PEDS-C45-062", "sec": "AIS puberty and management", "page": 210, "q": "In classical AIS, breast development at puberty is driven by testosterone converted to estrogen.", "opts": ["True", "False"], "ans": 0, "exp": "True — Increased testosterone is aromatized; the estrogen acts on breast tissue. (Book p210)", "type": "tf"},
 {"id": "PEDS-C45-063", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Precocious puberty in FEMALES is defined as pubertal changes before —", "opts": ["9 years", "9.5 years", "10 years", "8 years"], "ans": 3, "exp": "Pubertal changes occurring in females < 8 years. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-064", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Precocious puberty in MALES is defined as pubertal changes before —", "opts": ["9.5 years", "8 years", "10.5 years", "12 years"], "ans": 0, "exp": "Pubertal changes occurring in males < 9.5 years. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-065", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Central (gonadotropin-dependent) precocious puberty arises from disorders of the —", "opts": ["Peripheral tissues", "Hypothalamus and pituitary", "Gonads", "Adrenals"], "ans": 1, "exp": "Central/gonadotropin-dependent: disorders in hypothalamus-pituitary. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-066", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "The most common cause of central precocious puberty in FEMALES is —", "opts": ["Hydrocephalus", "CNS tumour", "Idiopathic", "Hypothalamic hamartoma"], "ans": 2, "exp": "Idiopathic: m/c in females. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-067", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "The most common cause of central precocious puberty in MALES is —", "opts": ["Idiopathic", "Adrenal tumour", "Testicular tumour", "CNS pathology"], "ans": 3, "exp": "CNS pathology: m/c in males. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-068", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "The most common CNS lesion causing central precocious puberty is —", "opts": ["Hypothalamic hamartoma", "Craniopharyngioma", "Medulloblastoma", "Arachnoid cyst"], "ans": 0, "exp": "CNS pathology: hypothalamic hamartomas (m/c). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-069", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "A hypothalamic hamartoma may also cause gelactic seizures characterised by —", "opts": ["Night terrors", "Uncontrollable laughter", "Sudden falls", "Recurrent vomiting"], "ans": 1, "exp": "Other features: gelastic seizures (uncontrollable laughter). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-070", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Gelastic seizures, defined by uncontrollable ___, point to hypothalamic hamartoma with precocious puberty.", "opts": ["Rage", "Shivering", "Laughter", "Crying"], "ans": 2, "exp": "Gelastic seizures = uncontrollable laughter, associated with hypothalamic hamartomas. (Book p211)", "type": "fill"},
 {"id": "PEDS-C45-071", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "A 7-year-old boy has rapid growth, pubic hair and 8 ml testes; he also has brief daily fits of uncontrollable laughter. MRI shows a suprasellar mass. Diagnosis —", "opts": ["Congenital adrenal hyperplasia", "Leydig cell tumour", "McCune-Albright syndrome", "Hypothalamic hamartoma with central precocious puberty"], "ans": 3, "exp": "CNS pathology (m/c in males): hypothalamic hamartoma with gelastic seizures → central precocious puberty. (Book p211)", "type": "case", "stem": "A 7-year-old boy develops pubic hair, penile growth and accelerated height velocity over 6 months. Mother describes daily 30-second bouts of uncontrollable laughing. MRI shows a non-enhancing suprasellar mass."},
 {"id": "PEDS-C45-072", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Functioning tumours in peripheral precocious puberty are more commonly found in the —", "opts": ["Testis", "Ovary", "Adrenal", "Pituitary"], "ans": 0, "exp": "Functioning tumours: more common in testis → increased testosterone production. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-073", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Testicular tumours causing peripheral precocious puberty include —", "opts": ["Teratoma", "Leydig/Sertoli cell tumours", "Seminoma", "Yolk sac tumour"], "ans": 1, "exp": "Leydig/Sertoli cell tumours → increased testosterone production. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-074", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "The most common cause of an autonomously functioning ovarian cyst with precocious puberty is —", "opts": ["Granulosa tumour only", "Follicular cyst of infancy alone", "McCune-Albright syndrome", "Turner syndrome"], "ans": 2, "exp": "Autonomously functioning ovarian cyst: m/c McCune-Albright syndrome (increased estrogen production). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-075", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "CAH causing peripheral precocious puberty in males is due to deficiency of —", "opts": ["17-α-hydroxylase", "3-β-HSD", "Cholesterol desmolase", "21-hydroxylase and 11-β-hydroxylase"], "ans": 3, "exp": "Congenital adrenal hyperplasia: deficiency of 21-hydroxylase, 11-β-hydroxylase → precocious puberty in males. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-076", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "The sex in which CAH classically produces precocious puberty is —", "opts": ["Males", "Females", "Both equally", "Neither"], "ans": 0, "exp": "21-OH/11-β-OH deficiency → precocious puberty in males. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-077", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "In peripheral precocious puberty, gonadotropin levels are —", "opts": ["Measured to confirm diagnosis", "Suppressed/low", "Pulsatile high", "Normal for age"], "ans": 1, "exp": "Peripheral/gonadotropin-independent: sex steroids rise independent of gonadotropin stimulation. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-078", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "A 3-year-old girl has breast development, pubic hair and recurrent ovarian cysts with low LH/FSH but high estrogen. Likely diagnosis —", "opts": ["Hypothalamic hamartoma", "Turner syndrome", "McCune-Albright syndrome", "Central idiopathic precocious puberty"], "ans": 2, "exp": "Autonomously functioning ovarian cyst (m/c with McCune-Albright) → increased estrogen, gonadotropin-independent puberty. (Book p211)", "type": "case", "stem": "A 3-year-old girl has thelarche and vaginal bleeding with a large ovarian cyst on ultrasound. LH and FSH are prepubertal; estradiol is very high. She also has bony deformity of the femur."},
 {"id": "PEDS-C45-079", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Match the precocious puberty cause with its category:", "opts": ["A-1, B-3, C-4, D-2", "A-3, B-4, C-1, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2"], "ans": 3, "exp": "Correct pairs: Idiopathic→Central, m/c in females; Hypothalamic hamartoma→Central, m/c in males; Leydig cell tumour→Peripheral (testis); CAH (21-OH)→Peripheral, males. (Book p211)", "type": "match", "pairs": [["Idiopathic", "Central, m/c in males"], ["Hypothalamic hamartoma", "Peripheral (testis)"], ["Leydig cell tumour", "Peripheral, males"], ["CAH (21-OH)", "Central, m/c in females"]]},
 {"id": "PEDS-C45-080", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Odd one out (peripheral precocious puberty causes):", "opts": ["Hypothalamic hamartoma", "Congenital adrenal hyperplasia", "Leydig cell tumour", "Autonomous ovarian cyst"], "ans": 0, "exp": "Hypothalamic hamartoma is a CENTRAL (gonadotropin-dependent) cause; the other three are peripheral/gonadotropin-independent. (Book p211)", "type": "odd"},
 {"id": "PEDS-C45-081", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "Central precocious puberty is gonadotropin-dependent.", "opts": ["True", "False"], "ans": 0, "exp": "True — Central = gonadotropin-dependent (hypothalamus-pituitary activation). (Book p211)", "type": "tf"},
 {"id": "PEDS-C45-082", "sec": "Precocious puberty definition and etiology", "page": 211, "q": "In males, pubertal changes before 8 years define precocious puberty.", "opts": ["True", "False"], "ans": 1, "exp": "False — In males the cut-off is < 9.5 years; < 8 years is the female cut-off. (Book p211)", "type": "tf"},
 {"id": "PEDS-C45-083", "sec": "McCune-Albright syndrome", "page": 211, "q": "McCune-Albright syndrome results from autonomous endocrine hyperfunction of one or more glands — thyroid, adrenal, ovaries and —", "opts": ["Parathyroid", "Pancreas", "Thymus", "Pituitary"], "ans": 3, "exp": "Autonomous endocrine hyperfunction of: thyroid, pituitary, adrenal gland, ovaries. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-084", "sec": "McCune-Albright syndrome", "page": 211, "q": "The genetic defect in McCune-Albright syndrome is —", "opts": ["GNAS1 gene mutation (gain of function)", "GNAS1 loss of function", "GPR54 mutation", "KISS1 mutation"], "ans": 0, "exp": "Genetic defect: GNAS1 gene mutation (gain of function). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-085", "sec": "McCune-Albright syndrome", "page": 211, "q": "The GNAS1 mutation in McCune-Albright is a ___ of function mutation.", "opts": ["Silent", "Gain", "Loss", "Dominant negative"], "ans": 1, "exp": "GNAS1 gene mutation (gain of function) → autonomous uncontrolled receptor activation. (Book p211)", "type": "fill"},
 {"id": "PEDS-C45-086", "sec": "McCune-Albright syndrome", "page": 211, "q": "GNAS1 codes for the α-subunit of ___ receptors.", "opts": ["Gq", "Gs and Gq both", "Gs", "Gi"], "ans": 2, "exp": "Codes for α-subunit of Gs receptors (→ constitutive cAMP signalling). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-087", "sec": "McCune-Albright syndrome", "page": 211, "q": "The functional consequence of the GNAS1 mutation is —", "opts": ["Receptor deletion", "Ligand overproduction", "Antibody-mediated stimulation", "Autonomous uncontrolled receptor activation"], "ans": 3, "exp": "Gain-of-function Gs α-subunit → autonomous uncontrolled receptor activation. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-088", "sec": "McCune-Albright syndrome", "page": 211, "q": "The clinical TRIAD of McCune-Albright syndrome includes polyendocrinopathy (precocious puberty), polyostotic fibrous dysplasia and —", "opts": ["Café-au-lait spots", "Neurofibromas", "Ash leaf spots", "Port-wine stain"], "ans": 0, "exp": "Triad: café-au-lait spots (skin finding), polyendocrinopathy (precocious puberty), polyostotic fibrous dysplasia. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-089", "sec": "McCune-Albright syndrome", "page": 211, "q": "Café-au-lait spots of McCune-Albright have —", "opts": ["Raised surface", "Irregular margins", "Regular margins", "Smooth round borders"], "ans": 1, "exp": "Irregular margins — \"Coast of Maine\" appearance; spots do not cross midline. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-090", "sec": "McCune-Albright syndrome", "page": 211, "q": "The café-au-lait spots of McCune-Albright are described by the coast of which region?", "opts": ["Norway", "Mexico", "Maine", "California"], "ans": 2, "exp": "Irregular margins, \"Coast of Maine\" appearance. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-091", "sec": "McCune-Albright syndrome", "page": 211, "q": "Café-au-lait spots in McCune-Albright —", "opts": ["Always cross the midline", "Occur only on the face", "Are present at birth always", "Do not cross the midline"], "ans": 3, "exp": "Spots do not cross midline. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-092", "sec": "McCune-Albright syndrome", "page": 211, "q": "Polyostotic fibrous dysplasia in McCune-Albright appears as —", "opts": ["Multiple lytic lesions in bones", "Osteosclerotic patches", "Periosteal reactions", "Fracture calluses"], "ans": 0, "exp": "Polyostotic fibrous dysplasia: multiple lytic lesions in bones. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-093", "sec": "McCune-Albright syndrome", "page": 211, "q": "The most common site of bony involvement in McCune-Albright fibrous dysplasia, besides proximal femur, is —", "opts": ["Ribs", "Base of skull", "Distal radius", "Spine"], "ans": 1, "exp": "M/c sites affected: base of skull; proximal femur → bowing (Shepherd crook deformity). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-094", "sec": "McCune-Albright syndrome", "page": 211, "q": "Bowing of the proximal femur in McCune-Albright is called —", "opts": ["Sabre shin", "Windswept deformity", "Shepherd's crook deformity", "Coxa vara only"], "ans": 2, "exp": "Proximal femur → bowing → Shepherd crook deformity. (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-095", "sec": "McCune-Albright syndrome", "page": 211, "q": "The femoral bowing deformity of polyostotic fibrous dysplasia is named after a ___'s crook.", "opts": ["Bishop", "Gardener", "Fisherman", "Shepherd"], "ans": 3, "exp": "Shepherd's crook deformity (proximal femur bowing). (Book p211)", "type": "fill"},
 {"id": "PEDS-C45-096", "sec": "McCune-Albright syndrome", "page": 211, "q": "Lytic lesions of the skull in McCune-Albright can be seen on —", "opts": ["X-ray skull", "USG skull only", "Fundus exam", "Otoscopy"], "ans": 0, "exp": "Lytic lesions in skull (with base of skull as a m/c site). (Book p211)", "type": "mcq"},
 {"id": "PEDS-C45-097", "sec": "McCune-Albright syndrome", "page": 211, "q": "A 4-year-old girl has precocious puberty, large irregular café-au-lait spots over one side of the body and a waddling gait with femoral bowing on X-ray. Diagnosis —", "opts": ["Polyostotic fibrous dysplasia alone", "McCune-Albright syndrome", "Neurofibromatosis type 1", "Hypothalamic hamartoma with PP"], "ans": 1, "exp": "Triad of precocious puberty (polyendocrinopathy), café-au-lait spots (Coast of Maine, not crossing midline) and polyostotic fibrous dysplasia (femoral bowing) = McCune-Albright. (Book p211)", "type": "case", "stem": "A 4-year-old girl has thelarche and vaginal bleeding, several large irregular café-au-lait patches on the right trunk/limb sparing the midline, and X-rays showing multiple lytic lesions with femoral bowing."},
 {"id": "PEDS-C45-098", "sec": "McCune-Albright syndrome", "page": 211, "q": "Match the McCune-Albright element with its detail:", "opts": ["A-3, B-4, C-1, D-2", "A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2"], "ans": 2, "exp": "Correct pairs: Gene→GNAS1 (Gs α-subunit); Skin→Café-au-lait, Coast of Maine; Bone→Shepherd crook deformity; Endocrine→Precocious puberty. (Book p211)", "type": "match", "pairs": [["Gene", "Café-au-lait, Coast of Maine"], ["Skin", "GNAS1 (Gs α-subunit)"], ["Bone", "Precocious puberty"], ["Endocrine", "Shepherd crook deformity"]]},
 {"id": "PEDS-C45-099", "sec": "McCune-Albright syndrome", "page": 212, "q": "Café-au-lait spots of neurofibromatosis-1 have —", "opts": ["Irregular margins", "Midline crossing", "Bullous surfaces", "Regular margins"], "ans": 3, "exp": "Note: NF-1 café-au-lait spots have regular margins — \"Coast of California\" appearance. (Book p212)", "type": "mcq"},
 {"id": "PEDS-C45-100", "sec": "McCune-Albright syndrome", "page": 212, "q": "\"Coast of California\" margins of café-au-lait spots indicate —", "opts": ["Neurofibromatosis-1", "McCune-Albright syndrome", "Tuberous sclerosis", "Legius syndrome"], "ans": 0, "exp": "NF-1 café-au-lait spots: regular margins, Coast of California appearance. (Book p212)", "type": "mcq"},
 {"id": "PEDS-C45-101", "sec": "McCune-Albright syndrome", "page": 212, "q": "Match the syndrome with its café-au-lait spot margin:", "opts": ["A-3, B-1, C-2, D-4", "A-3, B-1, C-4, D-2", "A-1, B-3, C-4, D-2", "A-3, B-4, C-1, D-2"], "ans": 1, "exp": "Correct pairs: McCune-Albright→Irregular, Coast of Maine; NF-1→Regular, Coast of California; McCune-Albright spots→Do not cross midline; Tuberous sclerosis→Ash-leaf (hypomelanotic) macules. (Book p211–212)", "type": "match", "pairs": [["McCune-Albright", "Regular, Coast of California"], ["NF-1", "Irregular, Coast of Maine"], ["McCune-Albright spots", "Ash-leaf (hypomelanotic) macules"], ["Tuberous sclerosis", "Do not cross midline"]]},
 {"id": "PEDS-C45-102", "sec": "McCune-Albright syndrome", "page": 212, "q": "Café-au-lait spots of McCune-Albright cross the midline.", "opts": ["True", "False"], "ans": 1, "exp": "False — The spots do not cross midline (and have irregular Coast-of-Maine margins). (Book p211)", "type": "tf"},
 {"id": "PEDS-C45-103", "sec": "McCune-Albright syndrome", "page": 212, "q": "The GNAS1 mutation in McCune-Albright is a loss-of-function mutation.", "opts": ["True", "False"], "ans": 1, "exp": "False — It is a gain-of-function mutation causing autonomous receptor activation. (Book p211)", "type": "tf"},
 {"id": "PEDS-C45-104", "sec": "McCune-Albright syndrome", "page": 212, "q": "Odd one out (McCune-Albright triad components):", "opts": ["Axillary freckling", "Precocious puberty", "Polyostotic fibrous dysplasia", "Café-au-lait spots"], "ans": 0, "exp": "Axillary freckling belongs to NF-1; the MAS triad is polyendocrinopathy (precocious puberty), polyostotic fibrous dysplasia and café-au-lait spots. (Book p211–212)", "type": "odd"},
 {"id": "PEDS-C45-105", "sec": "Precocious puberty treatment", "page": 212, "q": "The first principle of treating precocious puberty is —", "opts": ["Chemotherapy in all", "Treatment of the underlying condition", "Immediate GnRH analogue in all", "Observation in all"], "ans": 1, "exp": "Treatment: treatment of underlying condition. (Book p212)", "type": "mcq"},
 {"id": "PEDS-C45-106", "sec": "Precocious puberty treatment", "page": 212, "q": "Medical management of McCune-Albright precocious puberty uses —", "opts": ["Ketoconazole", "Tamoxifen", "Aromatase inhibitors (e.g., letrozole)", "GnRH analogues"], "ans": 2, "exp": "McCune-Albright syndrome: aromatase inhibitors (e.g., letrozole). (Book p212)", "type": "mcq"},
 {"id": "PEDS-C45-107", "sec": "Precocious puberty treatment", "page": 212, "q": "Aromatase inhibitors help in McCune-Albright by blocking the —", "opts": ["First step of estrogen synthesis", "Androgen receptor", "GnRH receptor", "Final step of estrogen synthesis"], "ans": 3, "exp": "Aromatase inhibitors block the final step of estrogen synthesis → decreased estrogen. (Book p212)", "type": "mcq"},
